<?php
declare(strict_types=1);
require __DIR__.'/inc/db.php';require __DIR__.'/inc/page.php';
$store=$pdo->query('SELECT name,address,phone,picture,open_time,close_time FROM stores WHERE is_active=1 ORDER BY id LIMIT 1')->fetch();page_start('Pickup location');
?><main class="container py-4" style="max-width:860px"><a href="view-all.php" class="d-inline-block mb-3">&larr; Back to menu</a><?php if(!$store):?><section class="app-card p-5 text-center"><h1 class="h4">Pickup is temporarily unavailable</h1><p class="help-text">The shop location has not been configured.</p></section><?php else:?><section class="app-card overflow-hidden"><?php if($store['picture']):?><img src="uploads/stores/<?=e(basename((string)$store['picture']))?>" alt="<?=e($store['name'])?>" style="width:100%;height:280px;object-fit:cover"><?php endif;?><div class="p-4 p-md-5"><div class="eyebrow">Pickup location</div><h1 class="h3"><?=e($store['name'])?></h1><p><?=nl2br(e($store['address']))?></p><dl class="row"><dt class="col-sm-4">Business hours</dt><dd class="col-sm-8"><?=e(substr((string)$store['open_time'],0,5))?>-<?=e(substr((string)$store['close_time'],0,5))?></dd><dt class="col-sm-4">Contact</dt><dd class="col-sm-8"><?=e($store['phone'])?></dd></dl><a href="view-all.php" class="btn btn-purple">Browse cakes</a></div></section><?php endif;?></main><?php page_end();
